/// A Hebrew ribbon starts its row at the window's right edge and runs left, the mirror of the
/// English one: Home › Clipboard is the rightmost group, and Font is drawn to its left.
#[test]
fn a_hebrew_ribbon_starts_at_the_right() {
    let mut app = WordApp::new(Session::new(wordcraft_engine::sample::sample_document()), crate::Services::default());
    app.run("ui.tab", json!({"tab": "Home"})).unwrap();
    let width = 2560.0;
    let mut h = egui_kittest::Harness::builder().with_size(vec2(width, 900.0)).build_ui_state(
        |ui, app: &mut WordApp| {
            let ctx = ui.ctx().clone();
            app.logic(&ctx);
            app.ui(ui);
        },
        app,
    );
    let mut boxes = std::collections::HashMap::new();
    for lang in ["en", "he"] {
        h.state_mut().run("ui.language", json!({"value": lang})).unwrap();
        h.run_steps(4);
        crate::widgets::GROUP_RECTS.with(|g| g.borrow_mut().clear());
        h.run_steps(1);
        // The last frame's boxes: a step may draw more than one.
        let found: std::collections::HashMap<String, egui::Rect> = crate::widgets::GROUP_RECTS.with(|g| g.borrow().iter().cloned().collect());
        boxes.insert(lang, found);
    }
    let (Some(en), Some(he)) = (boxes.get("en"), boxes.get("he")) else { panic!("both ribbons drew groups: {boxes:?}") };
    let (Some(en_clipboard), Some(en_font)) = (en.get("Clipboard"), en.get("Font")) else {
        panic!("the English Home tab shows Clipboard and Font: {en:?}")
    };
    let (Some(he_clipboard), Some(he_font)) = (he.get("Clipboard"), he.get("Font")) else {
        panic!("the Hebrew Home tab shows Clipboard and Font: {he:?}")
    };
    assert!(en_clipboard.min.x < en_font.min.x, "English runs left to right: {en_clipboard:?} {en_font:?}");
    assert!(he_clipboard.max.x > width - 40.0, "the Hebrew row starts at the right edge: {he_clipboard:?}");
    assert!(he_font.max.x <= he_clipboard.min.x + 0.5, "Font is drawn to the left of Clipboard: {he_clipboard:?} {he_font:?}");
}

/// The alignment buttons and the text directions are the one row whose order does not simply
/// reverse in a Hebrew interface: their icons face the way the text does, so the row keeps the
/// paragraph's reading order and starts, on the right, with Align Right and right-to-left.
#[test]
fn a_hebrew_alignment_row_starts_with_align_right() {
    let mut app = WordApp::new(Session::new(wordcraft_engine::sample::sample_document()), crate::Services::default());
    app.run("ui.tab", json!({"tab": "Home"})).unwrap();
    let mut h = egui_kittest::Harness::builder().with_size(vec2(2560.0, 900.0)).build_ui_state(
        |ui, app: &mut WordApp| {
            let ctx = ui.ctx().clone();
            app.logic(&ctx);
            app.ui(ui);
        },
        app,
    );
    let mut rows = std::collections::HashMap::new();
    for lang in ["en", "he"] {
        h.state_mut().run("ui.language", json!({"value": lang})).unwrap();
        h.run_steps(4);
        crate::widgets::BUTTON_RECTS.with(|b| b.borrow_mut().clear());
        h.run_steps(1);
        // The last frame's boxes: a step may draw more than one.
        let found: std::collections::HashMap<String, egui::Rect> = crate::widgets::BUTTON_RECTS.with(|b| b.borrow().iter().cloned().collect());
        rows.insert(lang, found);
    }
    let (Some(en), Some(he)) = (rows.get("en"), rows.get("he")) else { panic!("both ribbons drew buttons: {rows:?}") };
    // The boxes are keyed by the command a button runs (`small` records the `ButtonAction`'s id).
    let (align_left, center, align_right, justify) = ("para.alignLeft", "para.alignCenter", "para.alignRight", "para.justify");
    let (text_ltr, text_rtl) = ("para.ltr", "para.rtl");
    for (name, boxes) in [("en", en), ("he", he)] {
        for id in [align_left, center, align_right, justify, text_ltr, text_rtl] {
            assert!(boxes.contains_key(id), "the {name} Home tab shows {id}: {:?}", boxes.keys());
        }
    }
    // English: left, center, right, justify — then left-to-right, right-to-left.
    assert!(en[align_left].min.x < en[center].min.x);
    assert!(en[center].min.x < en[align_right].min.x);
    assert!(en[align_right].min.x < en[justify].min.x);
    assert!(en[text_ltr].min.x < en[text_rtl].min.x);
    // Hebrew: the row runs right to left and keeps the paragraph's order, so Align Right is the
    // rightmost of the four and the directions start with right-to-left.
    assert!(he[align_right].min.x > he[center].min.x, "Align Right is right of Center: {:?} {:?}", he[align_right], he[center]);
    assert!(he[center].min.x > he[align_left].min.x, "Center is right of Align Left: {:?} {:?}", he[center], he[align_left]);
    assert!(he[align_left].min.x > he[justify].min.x, "Align Left is right of Justify: {:?} {:?}", he[align_left], he[justify]);
    assert!(he[text_rtl].min.x > he[text_ltr].min.x, "the directions start with right-to-left: {:?} {:?}", he[text_rtl], he[text_ltr]);
}

// A frame that panics names itself: the language and tab it was drawing, what the panic said
// and where in this crate it came from. A report of a failed run keeps the first line of a
// failure and little else, so all of it goes on that one line.
let drawing = std::sync::Arc::new(std::sync::Mutex::new(String::new()));
let previous = std::sync::Arc::new(std::sync::Mutex::new(Some(std::panic::take_hook())));
{
    let (drawing, previous) = (drawing.clone(), previous.clone());
    std::panic::set_hook(Box::new(move |info| {
        let context = drawing.lock().map(|c| c.clone()).unwrap_or_default();
        eprintln!("PANIC while drawing {context}: {} — {}", panic_message(info.payload()), drawn_by(8));
        if let Some(previous) = previous.lock().unwrap().as_ref() {
            previous(info);
        }
    }));
}
/// What a caught panic said, as text.
fn panic_message(panic: &(dyn std::any::Any + Send)) -> String {
    if let Some(m) = panic.downcast_ref::<&str>() {
        (*m).to_string()
    } else if let Some(m) = panic.downcast_ref::<String>() {
        m.clone()
    } else {
        "a panic without a message".to_string()
    }
}
/// The frames `limit` of the stack that belong to this crate, innermost first, as one line.
fn drawn_by(limit: usize) -> String {
    let trace = std::backtrace::Backtrace::force_capture().to_string();
    let frames: Vec<&str> = trace
        .lines()
        .map(str::trim)
        .filter(|line| line.contains("wordcraft") || line.contains("ui_egui") || line.contains("ribbon"))
        .take(limit)
        .collect();
    if frames.is_empty() { "no frames of ours on the stack".to_string() } else { frames.join(" <- ") }
}

